// Asteroid Escape game
// Canvas element with id "game" is expected in the HTML.

const canvas = document.getElementById('game');
if (!canvas) {
  throw new Error('Canvas element with id "game" not found');
}
const ctx = canvas.getContext('2d');

// Adjust canvas size to fill its container
function resize() {
  const rect = canvas.getBoundingClientRect();
  canvas.width = rect.width;
  canvas.height = rect.height;
}
window.addEventListener('resize', resize);
resize();

// Game state
let ship = { x: canvas.width / 2, y: canvas.height - 60, width: 30, height: 30, speed: 4 };
let asteroids = [];
let orbs = [];
let score = 0;
let highScore = Number(localStorage.getItem('highScore')) || 0;
let lives = 3;
let gameOver = false;

// Input handling
const keys = {};
window.addEventListener('keydown', e => { keys[e.key] = true; });
window.addEventListener('keyup', e => { keys[e.key] = false; });

function spawnAsteroid() {
  const size = Math.random() * 30 + 20;
  const x = Math.random() * (canvas.width - size);
  const speed = Math.random() * 2 + 1;
  asteroids.push({ x, y: -size, size, speed });
}

function spawnOrb() {
  const radius = 8;
  const x = Math.random() * (canvas.width - radius * 2) + radius;
  const speed = 1.5;
  orbs.push({ x, y: -radius, radius, speed });
}

// Timers
setInterval(spawnAsteroid, 1200);
setInterval(spawnOrb, 3000);

function update() {
  if (gameOver) return;
  // Ship movement (arrow keys or WASD)
  if (keys.ArrowLeft || keys.a) ship.x -= ship.speed;
  if (keys.ArrowRight || keys.d) ship.x += ship.speed;
  if (keys.ArrowUp || keys.w) ship.y -= ship.speed;
  if (keys.ArrowDown || keys.s) ship.y += ship.speed;
  // Keep ship in bounds
  ship.x = Math.max(0, Math.min(canvas.width - ship.width, ship.x));
  ship.y = Math.max(0, Math.min(canvas.height - ship.height, ship.y));

  // Move asteroids
  for (let i = asteroids.length - 1; i >= 0; i--) {
    const a = asteroids[i];
    a.y += a.speed;
    // Collision with ship (simple AABB)
    if (
      ship.x < a.x + a.size &&
      ship.x + ship.width > a.x &&
      ship.y < a.y + a.size &&
      ship.y + ship.height > a.y
    ) {
      lives--;
      asteroids.splice(i, 1);
      if (lives <= 0) {
        gameOver = true;
        if (score > highScore) {
          highScore = score;
          localStorage.setItem('highScore', highScore);
        }
      }
      continue;
    }
    // Remove off‑screen
    if (a.y > canvas.height) asteroids.splice(i, 1);
  }

  // Move orbs
  for (let i = orbs.length - 1; i >= 0; i--) {
    const o = orbs[i];
    o.y += o.speed;
    const dx = (ship.x + ship.width / 2) - o.x;
    const dy = (ship.y + ship.height / 2) - o.y;
    const dist = Math.hypot(dx, dy);
    if (dist < o.radius + Math.max(ship.width, ship.height) / 2) {
      score++;
      orbs.splice(i, 1);
      continue;
    }
    if (o.y - o.radius > canvas.height) orbs.splice(i, 1);
  }
}

function drawStarfield() {
  // Simple static starfield background
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#444';
  for (let i = 0; i < 100; i++) {
    const sx = Math.random() * canvas.width;
    const sy = Math.random() * canvas.height;
    ctx.fillRect(sx, sy, 1, 1);
  }
}

function draw() {
  drawStarfield();

  // Draw ship (triangle)
  ctx.save();
  ctx.translate(ship.x + ship.width / 2, ship.y + ship.height / 2);
  ctx.fillStyle = '#0f0';
  ctx.beginPath();
  ctx.moveTo(0, -ship.height / 2);
  ctx.lineTo(-ship.width / 2, ship.height / 2);
  ctx.lineTo(ship.width / 2, ship.height / 2);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  // Draw asteroids
  ctx.fillStyle = '#888';
  asteroids.forEach(a => {
    ctx.beginPath();
    ctx.arc(a.x + a.size / 2, a.y + a.size / 2, a.size / 2, 0, Math.PI * 2);
    ctx.fill();
  });

  // Draw orbs
  ctx.fillStyle = '#ff0';
  orbs.forEach(o => {
    ctx.beginPath();
    ctx.arc(o.x, o.y, o.radius, 0, Math.PI * 2);
    ctx.fill();
  });

  // UI
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.fillText(`Score: ${score}`, 10, 20);
  ctx.fillText(`Lives: ${lives}`, 10, 40);
  ctx.fillText(`High: ${highScore}`, 10, 60);

  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#f00';
    ctx.textAlign = 'center';
    ctx.font = '32px sans-serif';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
  }
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

requestAnimationFrame(loop);
